        return 'D' if opp_defections >= 5 else 'C'
    if n >= 5:
        last5 = history[-5:]
        if all(m == 'D' and o == 'D' for m, o in last5):
            return 'C'
    recent = list(history[-6:])
    recent_def = sum(1 for m, o in recent if o == 'D')
    if recent_def == 0:
        return 'C'
    if recent_def >= 5:
        return 'D'
    if recent_def == 1:
        if opp_last == 'D' and my_last == 'C':
            return 'D'
        return 'C'
