        return 'D' if opp_last == 'D' else 'C'
    if recent_def == 3:
        if opp_last == 'D' and my_last == 'D':
            return 'D'
        return 'C'
    if recent_def == 4:
        if opp_last == 'D' and my_last == 'D':
            return 'D'
        return 'C'
    return 'C'
